  const state = { language: localStorage.getItem('nanoclaw-language') || 'zh', activeView:'chat', rates:null, socket:null, reconnectTimer:null, workflowRefreshTimer:null, knowledgeRefreshTimer:null, knowledgeData:null, knowledgeStatusById:{}, conversations:[], activeConversationId:localStorage.getItem('nanoclaw-active-conversation'), messagesByConversation:{}, filesByConversation:{}, workflowRuns:{}, activeWorkflowRunId:null, emailProviders:[], emailAccounts:[], emailAccountsError:'', emailAdminToken:'local-workspace', emailLoaded:false, emailActiveTab:'accounts', emailInboundItems:[], emailInboundDetail:null, emailInboundEtag:'', emailReviewChanges:{}, emailReviewPreview:null, emailRuntime:null, emailSendable:[], emailDeliveries:[] };
  const activeFiles=()=>state.filesByConversation[state.activeConversationId]||(state.filesByConversation[state.activeConversationId]=[]);
  const t = (key, vars={}) => Object.entries(vars).reduce((s,[k,v]) => s.replace(`{${k}}`,v), translations[state.language][key] || translations.en[key] || key);
  const setLanguage = lang => { state.language=translations[lang]?lang:'zh'; localStorage.setItem('nanoclaw-language',state.language); document.documentElement.lang=state.language==='zh'?'zh-CN':state.language; $('#languageCode').textContent={zh:'中',en:'EN',de:'DE'}[state.language]; $$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n)); $$('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder)); $$('[data-i18n-title]').forEach(el=>{el.title=t(el.dataset.i18nTitle);el.setAttribute('aria-label',t(el.dataset.i18nTitle))}); renderConversations(); renderWorkflow(); renderConversion(); renderPopular();if(state.knowledgeData)renderKnowledge(state.knowledgeData); renderEmailAccounts(); renderEmailProviderSummary(); renderEmailRuntime(); const selected=state.emailAccounts.find(item=>item.account_id===$('#emailAccountId')?.value);if(selected)renderEmailToggle(selected); window.dispatchEvent(new CustomEvent('nanoclaw:language-change',{detail:{language:state.language}})); };
  const showToast = message => { const toast=$('#toast'); toast.textContent=message; toast.classList.add('show'); clearTimeout(showToast.timer); showToast.timer=setTimeout(()=>toast.classList.remove('show'),2600); };
  const knowledgeErrorMessage=code=>t(`knowledge.error.${code||''}`)!==`knowledge.error.${code||''}`?t(`knowledge.error.${code}`):(code||t('knowledge.failed'));
  const uploadErrorMessage = code => ({unsupported_file_type:t('file.unsupported'),file_too_large:t('file.tooLarge'),file_must_be_utf8:t('file.invalidUtf8'),invalid_json:t('file.invalidJson'),empty_file:t('file.empty'),pdf_needs_ocr:t('knowledge.ocr')}[code] || knowledgeErrorMessage(code));
  const closeImportMenu=()=>{$('#importMenu').classList.remove('open');$('#importToggle').setAttribute('aria-expanded','false')};
  const renderConversationFiles=()=>{const files=activeFiles(),host=$('#conversationFiles');host.innerHTML='';host.classList.toggle('has-files',files.length>0);files.forEach((file,index)=>{const chip=document.createElement('span');chip.className='file-chip';const label=document.createElement('span');label.textContent=file.name;label.title=file.name;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.title=t('file.remove');remove.setAttribute('aria-label',t('file.remove'));remove.addEventListener('click',()=>{const [removed]=files.splice(index,1);renderConversationFiles();showToast(t('file.removed',{name:removed.name}))});chip.append(label,remove);host.append(chip)})};
  const postFile=async(file,mode)=>{const endpoint=mode==='conversation'?'/api/files/read':'/api/knowledge/import';const contentType=mode==='knowledge'&&file.type?file.type:'application/octet-stream';const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':contentType,'X-File-Name':encodeURIComponent(file.name)},body:file});const data=await response.json().catch(()=>({detail:`HTTP ${response.status}`}));if(!response.ok)throw new Error(uploadErrorMessage(data.detail));return data};
  const importConversationFile=async file=>{if(!file)return;const files=activeFiles();if(files.length>=3){showToast(t('file.tooMany'));return}try{const data=await postFile(file,'conversation');const next=files.filter(item=>item.name!==data.name);if(next.reduce((sum,item)=>sum+item.content.length,0)+data.content.length>120000){showToast(t('file.contextTooLarge'));return}state.filesByConversation[state.activeConversationId]=[...next,{...data,sent:false}];renderConversationFiles();showToast(t('file.readSuccess',{name:data.name}))}catch(error){showToast(t('file.uploadFailed',{reason:error.message}))}};
  const importKnowledgeFile=async file=>{if(!file)return;let documentId='';try{const data=await postFile(file,'knowledge');documentId=data.document_id;const key=data.content_type==='application/pdf'&&!data.duplicate?'file.knowledgeQueued':data.duplicate?'file.knowledgeDuplicate':'file.knowledgeSuccess';showToast(t(key,{name:data.name}))}catch(error){showToast(t('file.uploadFailed',{reason:error.message}))}finally{await loadKnowledge();if(documentId)await showKnowledgeDetail(documentId)}};
  const setTheme = theme => { document.documentElement.dataset.theme=theme; localStorage.setItem('nanoclaw-theme',theme); };
  const initialTheme = localStorage.getItem('nanoclaw-theme') || (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'); setTheme(initialTheme);
  $('#themeToggle').addEventListener('click',()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
  $('#languageToggle').addEventListener('click',e=>{e.stopPropagation();const menu=$('#languageMenu');menu.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',menu.classList.contains('open'))});
  $$('[data-language]').forEach(button=>button.addEventListener('click',()=>{setLanguage(button.dataset.language);$('#languageMenu').classList.remove('open')})); document.addEventListener('click',()=>{$('#languageMenu').classList.remove('open');closeImportMenu()});
  const setView = view => {state.activeView=view;document.body.classList.toggle('non-chat-view',view!=='chat');$$('.rail-button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); $$('.view').forEach(v=>v.classList.toggle('active',v.id===`${view}View`));if(['email','trade'].includes(view))$('#workflowPanel').hidden=true;else renderWorkflow();if(view==='rates'&&!state.rates) fetchRates();if(view==='knowledge')loadKnowledge();else{clearTimeout(state.knowledgeRefreshTimer);state.knowledgeRefreshTimer=null}if(view==='email')loadEmailWorkspace(); };
  $$('.rail-button[data-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));
  const emailErrorKey=code=>({email_feature_not_implemented:'email.notImplemented',email_admin_unauthorized:'email.unauthorized',email_admin_auth_not_configured:'email.authNotConfigured',email_admin_origin_forbidden:'email.originForbidden',email_review_pending_fields:'email.reviewInvalid',email_reviewer_not_configured:'email.reviewerNotConfigured',email_review_version_conflict:'email.reviewConflict',email_review_idempotency_conflict:'email.reviewConflict',email_review_superseded:'email.reviewConflict',email_review_invalid_request:'email.reviewInvalid',email_review_invalid_evidence:'email.reviewEvidenceInvalid',email_review_invalid_reason:'email.reviewReasonInvalid',email_review_validation_failed:'email.reviewInvalid',email_approval_not_found:'email.approvalUnavailable',email_approval_already_decided:'email.approvalUnavailable',email_approval_quote_stale:'email.approvalRegenerate',email_approval_regeneration_required:'email.approvalRegenerate'}[code]||'email.requestFailed');
  const setEmailApiStatus=(kind,key)=>{const badge=$('#emailApiStatus');badge.className=`email-api-status ${kind}`;badge.textContent=t(key)};
  const setEmailFormStatus=(key,kind='')=>{const badge=$('#emailFormStatus');badge.className=`email-form-status ${kind}`;badge.textContent=t(key)};
  const emailHeaders=(withJson=false)=>{const headers={};if(withJson)headers['Content-Type']='application/json';return headers};
  const emailRequest=async(path,options={})=>{const response=await fetch(path,{...options,headers:{...emailHeaders(Boolean(options.body)),...(options.headers||{})}});const data=await response.json().catch(()=>({detail:'email_request_failed'}));return {response,data}};
  const workStatusKey=status=>({awaiting_field_review:'email.awaitingFieldReview',quote_blocked:'email.quoteBlocked',pending_approval:'email.pendingApproval',approved:'email.approvedForQueue',rejected:'email.rejectedQuote'}[status]||'email.requestFailed');
  const openInboundWorkItem=async item=>{setView('email');const tabButton=$('[data-email-tab="inbound"]');tabButton?.click();if(item.email_id)await loadInboundDetail(item.email_id)};
  const decideEmailApproval=async(item,action)=>{const promptKey=action==='approve'?'email.approvalConfirm':'email.rejectConfirm';if(!window.confirm(t(promptKey)))return;try{const {response,data}=await emailRequest(`/api/email/approvals/${encodeURIComponent(item.approval_key)}/decision`,{method:'POST',body:JSON.stringify({action})});if(!response.ok){handleEmailProtectedError(response,data);showToast(t(emailErrorKey(data.detail)));return}showToast(t('email.approvalUpdated'));await loadEmailOverview();if(state.emailActiveTab==='sendable')await loadEmailSendable()}catch(_error){showToast(t('email.requestFailed'))}};
  const loadEmailOverview=async()=>{try{const {response,data}=await emailRequest('/api/email/metrics');if(!response.ok){handleEmailProtectedError(response,data);return}$('#emailMetricPending').textContent=String(data.agent_review_queue||0);$('#emailMetricSendable').textContent=String(data.sendable_approvals||0);$('#emailMetricActive').textContent=String(data.active_deliveries||0);$('#emailMetricAccepted').textContent=String(data.accepted_today||0)}catch(_error){['#emailMetricPending','#emailMetricSendable','#emailMetricActive','#emailMetricAccepted'].forEach(selector=>$(selector).textContent='—')}};
